class CustomerRow extends DataClass implements Insertable<CustomerRow> {
  final String id;
  final String name;
  final String? phone;
  final String? secondaryPhone;
  final String? email;
  final String? address;

  /// 1 = credit/account allowed (§4.11).
  final bool hasAccount;
  final int? dateOfBirth;
  final String? gender;
  final String? medicalHistory;
  final String? taxVatNumber;
  final int openingBalanceMicros;
  final int balanceMicros;
  final int creditLimitMicros;
  final String? notes;
  final bool isActive;
  final int createdAt;
  final int updatedAt;
  const CustomerRow({
    required this.id,
    required this.name,
    this.phone,
    this.secondaryPhone,
    this.email,
    this.address,
    required this.hasAccount,
    this.dateOfBirth,
    this.gender,
    this.medicalHistory,
    this.taxVatNumber,
    required this.openingBalanceMicros,
    required this.balanceMicros,
    required this.creditLimitMicros,
    this.notes,
    required this.isActive,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || secondaryPhone != null) {
      map['secondary_phone'] = Variable<String>(secondaryPhone);
    }
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    if (!nullToAbsent || address != null) {
      map['address'] = Variable<String>(address);
    }
    map['has_account'] = Variable<bool>(hasAccount);
    if (!nullToAbsent || dateOfBirth != null) {
      map['date_of_birth'] = Variable<int>(dateOfBirth);
    }
    if (!nullToAbsent || gender != null) {
      map['gender'] = Variable<String>(gender);
    }
    if (!nullToAbsent || medicalHistory != null) {
      map['medical_history'] = Variable<String>(medicalHistory);
    }
    if (!nullToAbsent || taxVatNumber != null) {
      map['tax_vat_number'] = Variable<String>(taxVatNumber);
    }
    map['opening_balance_micros'] = Variable<int>(openingBalanceMicros);
    map['balance_micros'] = Variable<int>(balanceMicros);
    map['credit_limit_micros'] = Variable<int>(creditLimitMicros);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<int>(createdAt);
    map['updated_at'] = Variable<int>(updatedAt);
    return map;
  }

